function entry(
  key: string,
  displayName: string,
  background: string,
  paths: [string, string][],
  keywords: string,
  outline = rounded,
) {
  const name = `generic-${key}`;
  const metadata: IconMetadata = {
    name,
    displayName,
    category: "development-ai",
    keywords: keywords.split(" "),
    defaultColor: "currentColor",
  };
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="1em" height="1em"><path fill="${background}" d="${outline}"/>${paths.map(([fill, d]) => `<path fill="${fill}" d="${d}"/>`).join("")}</svg>`;
  return { name, metadata, svg };
}

