export const builtinIconList = entries.map(({ name }) => name);

export function randomBuiltinIcon(): string {
  return builtinIconList[Math.floor(Math.random() * builtinIconList.length)];
}

export const builtinIcons: Record<string, string> = Object.fromEntries(
  entries.map(({ name, svg }) => [name, svg]),
);
export const builtinIconMetadata: Record<string, IconMetadata> =
  Object.fromEntries(entries.map(({ name, metadata }) => [name, metadata]));

export function searchBuiltinIcons(
  query: string,
  localizedLabel?: (name: string) => string,
): string[] {
  const normalized = query.trim().toLowerCase();
  return entries
    .filter(({ metadata }) =>
      [
        metadata.name,
        metadata.displayName,
        ...metadata.keywords,
        localizedLabel?.(metadata.name) ?? "",
      ].some((value) => value.toLowerCase().includes(normalized)),
    )
    .map(({ name }) => name);
}
